#ifndef MAIN_MANIFEST_H
#define MAIN_MANIFEST_H
/* MAIN.agc of each mission as native data: its include list in assembly
 * order, with the fixed words each included file emits in the assembled
 * program (src/main_manifest.c, generated by tools/main_assembly.py from
 * yaYUL's listing; docs/MAIN-ASSEMBLY.md). */
#include <stdint.h>
typedef struct {uint16_t start,count;} main_manifest_run;   /* physical words */
typedef struct {
 const char *file;           /* the checked-in source file, as MAIN.agc includes it */
 uint16_t first_run,runs;    /* its runs in the mission's run table */
 uint16_t words;             /* fixed words it emits */
 uint32_t sum;               /* their sum, modulo 2^32 */
} main_manifest_file;
typedef struct {
 const main_manifest_file *files;uint8_t file_count;
 const main_manifest_run *runs;uint16_t run_count;
 const uint16_t *checksum_at;   /* the 36 bank checksum words (BNKSUM), written by the assembler */
 uint16_t emitted;              /* fixed words emitted by the included files */
} main_manifest;
extern const main_manifest main_manifests[2];  /* 0 Luminary099, 1 Comanche055 */
/* Checks mission's manifest against the rope (include/rope_image.h): each
 * file's word count and sum, no word emitted twice, and every other word an
 * unused-word fill (+0, or TC to itself) or a bank checksum. Adds to *checks;
 * returns the failures. */
unsigned main_manifest_check(unsigned mission,uint16_t *checks);
#endif
